from datetime import datetime

class Scheduler:
    def __init__(self) -> None:
        self.appointments = []
        self.appointment_id_counter = 0
        self.patient_appointments = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime, now: datetime) -> int:
        """
        Book an appointment; returns its id. `now` is the current time.

        Raises:
            ValueError: If the appointment starts before the current time.
            ValueError: If the appointment overlaps with another appointment of the same doctor.
            ValueError: If the patient already has an upcoming appointment.
        """
        if start < now:
            raise ValueError("Appointment cannot start before the current time")

        # Check if the patient already has an upcoming appointment
        if patient in self.patient_appointments:
            existing_appointment = self.patient_appointments[patient]
            if existing_appointment['end'] > now:
                raise ValueError("Patient already has an upcoming appointment")

        # Check for overlapping appointments with the same doctor
        for appointment in self.appointments:
            if appointment['doctor'] == doctor and not (end <= appointment['start'] or start >= appointment['end']):
                raise ValueError("Appointment overlaps with another appointment of the same doctor")

        # Create a new appointment
        self.appointment_id_counter += 1
        appointment_id = self.appointment_id_counter
        self.appointments.append({
            'id': appointment_id,
            'patient': patient,
            'doctor': doctor,
            'start': start,
            'end': end
        })
        self.patient_appointments[patient] = {
            'id': appointment_id,
            'start': start,
            'end': end
        }

        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """
        Cancel an appointment.
        """
        for appointment in self.appointments:
            if appointment['id'] == appointment_id:
                if appointment['start'] < now:
                    raise ValueError("Cannot cancel a past appointment")
                self.appointments.remove(appointment)
                self.patient_appointments.pop(appointment['patient'])
                return
        raise ValueError("Appointment not found")

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """
        True if the doctor can be booked between start and end.
        """
        for appointment in self.appointments:
            if appointment['doctor'] == doctor and not (end <= appointment['start'] or start >= appointment['end']):
                return False
        return True
